def find_all_primitive_roots(p):
    """Find all primitive roots modulo p."""
    def is_primitive_root(g, p):
        phi = p - 1
        factors = set()
        n = phi
        d = 2
        while d * d <= n:
            while n % d == 0:
                factors.add(d)
                n //= d
            d += 1
        if n > 1:
            factors.add(n)

        for q in factors:
            if pow(g, phi // q, p) == 1:
                return False
        return True

    roots = []
    for g in range(2, p):
        if is_primitive_root(g, p):
            roots.append(g)
    return roots

def verify_costas(x):
    n = len(x)
    vectors = set()
    for i in range(n):
        for j in range(i+1, n):
            dr = x[j] - x[i]
            dc = j - i
            vec = (dr, dc)
            if vec in vectors:
                return False
            vectors.add(vec)
    return True

def lempel_construction(p, g):
    """Lempel construction for Costas array of order p-2."""
    n = p - 2

    # Compute powers of g: g^0, g^1, ..., g^(p-2)
    powers = [1] * (p - 1)
    for i in range(1, p - 1):
        powers[i] = (powers[i-1] * g) % p

    # Build inverse map: value -> exponent
    inv_powers = {powers[i]: i for i in range(p - 1)}

    # Lempel: x[i] = log_g(g^(i+1) + 1) - 1
    # Skip when g^(i+1) + 1 = 0 mod p
    x = []
    for i in range(p - 1):
        val = (powers[i] + 1) % p
        if val == 0:
            continue
        x.append(inv_powers[val] - 1)

    return x

def golomb_construction(p, g, h):
    """Golomb construction for Costas array of order p-2."""
    n = p - 2

    # Compute powers of g and h
    powers_g = [1] * (p - 1)
    powers_h = [1] * (p - 1)
    for i in range(1, p - 1):
        powers_g[i] = (powers_g[i-1] * g) % p
        powers_h[i] = (powers_h[i-1] * h) % p

    # Build inverse map for g
    inv_powers_g = {powers_g[i]: i for i in range(p - 1)}

    # Golomb: x[i] = log_g(h^(i+1) + 1) - 1
    # Skip when h^(i+1) + 1 = 0 mod p
    x = []
    for i in range(p - 1):
        val = (powers_h[i] + 1) % p
        if val == 0:
            continue
        x.append(inv_powers_g[val] - 1)

    return x

