def costas_search_optimized(n, max_time=55):
    """Backtracking search for Costas array with optimizations."""
    import time
    start_time = time.time()

    x = [-1] * n
    used_rows = [False] * n
    # vectors[dc][dr] = True if vector (dr, dc) exists
    # dc ranges from 1 to n-1, dr ranges from -(n-1) to (n-1)
    vectors = {}

    def backtrack(col):
        if time.time() - start_time > max_time:
            return None

        if col == n:
            return x[:]

        for row in range(n):
            if used_rows[row]:
                continue

            # Check if placing mark at (row, col) creates duplicate vectors
            valid = True
            new_vectors = []
            for prev_col in range(col):
                prev_row = x[prev_col]
                dr = row - prev_row
                dc = col - prev_col
                vec = (dr, dc)
                if vec in vectors:
                    valid = False
                    break
                new_vectors.append(vec)

            if not valid:
                continue

            # Place mark
            x[col] = row
            used_rows[row] = True
            for vec in new_vectors:
                vectors[vec] = True

            result = backtrack(col + 1)
            if result is not None:
                return result

            # Undo
            x[col] = -1
            used_rows[row] = False
            for vec in new_vectors:
                del vectors[vec]

        return None

    return backtrack(0)

